import{Mt as e,dt as t,n,pt as r}from"./chunks/framework.CaLsa5bj.js";var i=JSON.parse(`{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1794389503000}`),a={name:`guide/introduction.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p>Workflow 是面向 Vue 3 的工作流设计器。通过 <code>@bubblesjs/workflow-vue-core</code> 的 <code>Designer</code> 组件，你可以在应用中编排审批、填写、抄送、条件分支和循环流程。</p><p>流程结构保存在 <code>nodes</code> 数组中。设计器负责添加与删除节点、组织分支和循环、计算布局与连线；使用方负责业务表单、权限、数据持久化，以及与工作流引擎的对接。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to “能做什么”">​</a></h2><ul><li><strong>可视化编排</strong>：通过添加入口插入业务节点，自动维护条件分支、循环与退出结构。</li><li><strong>数据驱动</strong>：使用 <code>v-model:nodes</code> 接收完整节点数组，配置变更立即反映到画布。</li><li><strong>业务配置</strong>：监听 <code>node-click</code>，在自己的抽屉、弹窗或侧栏中编辑 <code>data.config</code>。</li><li><strong>只读展示</strong>：设置 <code>readonly</code> 隐藏编辑入口并禁用节点点击，保留画布平移与缩放。</li><li><strong>TypeScript 支持</strong>：通过 <code>WorkflowNode&lt;TConfig&gt;</code> 为业务数据声明类型。</li><li><strong>保存与恢复</strong>：序列化节点数组保存草稿，恢复数据后继续编辑。</li></ul><h2 id="从数据到画布" tabindex="-1">从数据到画布 <a class="header-anchor" href="#从数据到画布" aria-label="Permalink to “从数据到画布”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的应用                      Designer</span></span>
<span class="line"><span>nodes / data.config  ──────→  自动布局与连线</span></span>
<span class="line"><span>                     ←──────  添加、删除、增加条件</span></span>
<span class="line"><span>业务配置表单         ←──────  node-click { id, type }</span></span></code></pre></div><p>每个节点拥有唯一 <code>id</code>。同层节点的数组顺序表示执行顺序，<code>parentNode</code> 表示节点归属。无需存储连线，也无需手动维护坐标。</p><h2 id="当前范围" tabindex="-1">当前范围 <a class="header-anchor" href="#当前范围" aria-label="Permalink to “当前范围”">​</a></h2><p>当前公开包版本为 <code>0.1.0</code>，基于 Vue 3 和 Vue Flow。画布采用自动布局，支持只读展示，未开放拖拽节点、自定义连线和自定义节点插槽等配置；公开接口见 <a href="./../api/designer">Designer API</a>。</p><p>审批规则、表达式求值、人员选择与实际流程执行由业务系统实现。画布展示条件与循环结构，不会执行这些业务规则。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to “接下来”">​</a></h2><ul><li><a href="./getting-started">快速开始</a>：安装与挂载第一个设计器。</li><li><a href="./../examples/">交互示例</a>：添加节点、修改业务配置并查看数据。</li><li><a href="./nodes">节点与流程结构</a>：理解分支、循环和数据关系。</li><li><a href="./../development/">本地开发</a>：运行本仓库的 playground 和文档站点。</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};